"""The workflow graph is well formed and everything it refers to exists (generated by adk_v2/6.0.0)."""

from typing import Any

START, END = "__START__", "__END__"


def _targets(graph: dict) -> dict[str, list[str]]:
    out: dict[str, list[str]] = {}
    for e in graph["edges"]:
        out.setdefault(e["source"], []).append(e["target"])
    return out


def test_every_node_is_reachable_from_start(graph: dict):
    """Every node can be reached from the start marker."""
    out = _targets(graph)
    seen, todo = set(), list(out.get(START, []))
    while todo:
        n = todo.pop()
        if n in seen or n == END:
            continue
        seen.add(n)
        todo.extend(out.get(n, []))
    assert seen == {n["id"] for n in graph["nodes"]}, "unreachable nodes: " + str({n["id"] for n in graph["nodes"]} - seen)


def test_every_path_can_end(graph: dict):
    """Every node has a path to the end marker."""
    out = _targets(graph)
    can_end = {END}
    changed = True
    while changed:
        changed = False
        for n in graph["nodes"]:
            if n["id"] not in can_end and any(t in can_end for t in out.get(n["id"], [])):
                can_end.add(n["id"])
                changed = True
    assert {n["id"] for n in graph["nodes"]} <= can_end, "a node can never reach the end"


def test_references_resolve(workflow: Any, graph: dict):
    """Each prompt, model, tool and child a node names is part of the workflow."""
    for n in graph["nodes"]:
        cfg = n.get("config", {})
        if cfg.get("prompt"):
            assert cfg["prompt"] in workflow.prompts, f"{n['id']}: prompt {cfg['prompt']} not exported"
        if cfg.get("model"):
            assert cfg["model"] in workflow.models or "/" in cfg["model"], f"{n['id']}: model {cfg['model']} not exported"
        for t in cfg.get("tools", []):
            assert t in workflow.tools or any(t.startswith(m) for m in workflow.tools), f"{n['id']}: tool {t} not exported"
        if n["kind"] == "subflow":
            assert cfg["child"] in workflow.children, f"{n['id']}: child {cfg['child']} not bundled"


def test_labelled_routing_matches_the_condition(workflow: Any, graph: dict):
    """Each label a condition can return has an outgoing edge on its node."""
    out = {n["id"]: {e["label"] for e in graph["edges"] if e["source"] == n["id"] and e.get("label")} for n in graph["nodes"]}
    for n in graph["nodes"]:
        if n.get("routing") != "label" or not n.get("condition_id"):
            continue
        labels = set(workflow.conditions[n["condition_id"]].labels)
        assert labels <= out[n["id"]], f"{n['id']}: labels {labels - out[n['id']]} have no edge"
